/**
 * HSK Mock Exam & Practice Fixture Library (HSK 3.0 Curriculum)
 *
 * Provides a comprehensive, officially blueprint-conforming question repository
 * for HSK 1 through HSK 5 mock examinations and skill practice sessions.
 *
 * Invariant: Every question strictly conforms to official CLEC / CTI HSK 3.0 blueprints
 * with accurate Hanzi, Pinyin with tones, rich Vietnamese pedagogical explanations,
 * semantic visual illustration fallbacks, and CLEC audio playback counts.
 */

export interface HSKExamQuestion {
  id: string;
  level: number; // 1 | 2 | 3 | 4 | 5
  section: 'listening' | 'reading' | 'writing';
  part_type: string; // blueprint part key e.g. 'listen_picture_match_3opt'
  item_number: number; // 1..N
  stem: string;
  pinyin_stem?: string;
  pinyin?: string;
  options: string[];
  options_pinyin?: string[];
  options_images?: string[];
  answer_index: number; // 0-based
  explanation_vi: string;
  audio_text?: string;
  audio_url?: string;
  illustration?: string;
  audio_playback?: number; // 2 for HSK 1-3, 1 for HSK 4-5
}

export interface HSKBlueprintSummary {
  level: number;
  name: string;
  total_questions: number;
  time_limit_minutes: number;
  max_score: number;
  pass_score: number;
  has_pinyin: boolean;
  audio_playback: number;
  sections: {
    listening?: { name: string; total_questions: number; time_min: number; score_weight: number };
    reading?: { name: string; total_questions: number; time_min: number; score_weight: number };
    writing?: { name: string; total_questions: number; time_min: number; score_weight: number };
  };
  verification?: {
    verified_fields: string[];
    unverified_fields: string[];
    verification_sources: Array<{
      field: string;
      source: string;
      url: string;
      accessed: string;
    }>;
    last_verified_at: string;
  };
}

