export const HSK2_REPRESENTATIVE_FIXTURES: HSKExamQuestion[] = HSK2_FULL_MOCK_EXAM.slice(0, 6);
export const HSK3_REPRESENTATIVE_FIXTURES: HSKExamQuestion[] = HSK3_FULL_MOCK_EXAM.slice(0, 4);
export const HSK4_REPRESENTATIVE_FIXTURES: HSKExamQuestion[] = HSK4_FULL_MOCK_EXAM.slice(0, 3);
export const HSK5_REPRESENTATIVE_FIXTURES: HSKExamQuestion[] = HSK5_FULL_MOCK_EXAM.slice(0, 3);
export const HSK6_REPRESENTATIVE_FIXTURES: HSKExamQuestion[] = HSK6_FULL_MOCK_EXAM.slice(0, 3);

/**
 * Helper to get the complete mock exam question set for a given level
 */
export function getMockExamQuestions(level: number): HSKExamQuestion[] {
  if (level === 1) {
    return [...HSK1_FULL_MOCK_EXAM];
  }
  if (level === 2) {
    return [...HSK2_FULL_MOCK_EXAM];
  }
  if (level === 3) {
    return [...HSK3_FULL_MOCK_EXAM];
  }
  if (level === 4) {
    return [...HSK4_FULL_MOCK_EXAM];
  }
  if (level === 5) {
    return [...HSK5_FULL_MOCK_EXAM];
  }
  if (level === 6) {
    return [...HSK6_FULL_MOCK_EXAM];
  }
  return [...HSK1_FULL_MOCK_EXAM];
}

/**
 * Filter questions for Practice Mode by level, skill, or part_type
 */
export function getPracticeQuestions(
  level: number,
  skill?: string,
  part_type?: string,
  count = 10
): HSKExamQuestion[] {
  const normSkill = typeof skill === 'string' ? skill.toLowerCase().trim() : undefined;
  const isSpecificSkill = Boolean(normSkill && normSkill !== 'all');

  let pool: HSKExamQuestion[];

  // Special case: HSK 1 writing practice
  if (level === 1 && isSpecificSkill && normSkill === 'writing') {
    pool = [...HSK1_FOUNDATIONAL_WRITING];
  } else {
    pool = getMockExamQuestions(level);
    if (isSpecificSkill) {
      pool = pool.filter((q) => q.section.toLowerCase() === normSkill);
    }
  }

  if (part_type) {
    const pt = part_type.toLowerCase().trim();
    pool = pool.filter((q) => q.part_type.toLowerCase() === pt);
  }

  // Strictly DO NOT fallback to all questions when skill or part_type is specified!
  // If pool has fewer items than count, return all matching items without borrowing other sections.
  return pool.slice(0, Math.max(0, count));
}

/**
 * Lookup question by ID across all fixtures
 */
export function findQuestionById(id: string): HSKExamQuestion | undefined {
  if (!id) return undefined;

  const allFixtures: HSKExamQuestion[] = [
    ...HSK1_FULL_MOCK_EXAM,
    ...HSK2_FULL_MOCK_EXAM,
    ...HSK3_FULL_MOCK_EXAM,
    ...HSK4_FULL_MOCK_EXAM,
    ...HSK5_FULL_MOCK_EXAM,
    ...HSK1_FOUNDATIONAL_WRITING,
  ];

  const exact = allFixtures.find(q => q.id === id);
  if (exact) return exact;

  // Partial match fallback
  const baseId = id.split('-item')[0];
  return allFixtures.find(q => q.id === baseId);
}

